/** The result of a check: the value, or the rules it breaks. */
export type CheckResult<T> = { readonly ok: true; readonly domain: typeof DOMAIN; readonly value: T } | { readonly ok: false; readonly domain: typeof DOMAIN; readonly failures: readonly Failure[] };

/** The types of the definitions, by name. */
export interface DefinitionTypes {
  readonly role: Role;
  readonly caller: Caller;
  readonly utc_time: UtcTime;
  readonly now: Now;
  readonly idempotency_key: IdempotencyKey;
  readonly sku: Sku;
  readonly location: Location;
  readonly quantity: Quantity;
  readonly requested: Requested;
  readonly on_hand: OnHand;
  readonly reserved: Reserved;
  readonly available: Available;
  readonly line: Line;
  readonly receipt_lines: ReceiptLines;
  readonly reserve_lines: ReserveLines;
  readonly ship_lines: ShipLines;
  readonly stock_level: StockLevel;
  readonly stored_level: StoredLevel;
  readonly stored_levels: StoredLevels;
  readonly levels: Levels;
  readonly level: Level;
  readonly short_line: ShortLine;
  readonly short_lines: ShortLines;
  readonly purchase_order_id: PurchaseOrderId;
  readonly reservation_id: ReservationId;
  readonly order_id: OrderId;
  readonly ttl_minutes: TtlMinutes;
  readonly result: Result;
  readonly state: State;
  readonly expires_at: ExpiresAt;
  readonly shipped: Shipped;
  readonly reserved_line: ReservedLine;
  readonly reservation_lines: ReservationLines;
  readonly reservation: Reservation;
  readonly stored_reservation: StoredReservation;
  readonly open_reservation: OpenReservation;
  readonly delta: Delta;
  readonly reason: Reason;
  readonly event_id: EventId;
  readonly event_type: EventType;
  readonly quantity_changed: QuantityChanged;
  readonly occurred_at: OccurredAt;
  readonly stock_event: StockEvent;
  readonly events: Events;
  readonly stock_depleted: StockDepleted;
  readonly depletions: Depletions;
  readonly error_code: ErrorCode;
  readonly expected_code: ExpectedCode;
  readonly error_message: ErrorMessage;
  readonly invalid_request: InvalidRequest;
  readonly unknown_sku: UnknownSku;
  readonly unknown_location: UnknownLocation;
  readonly insufficient_stock: InsufficientStock;
  readonly reservation_not_found: ReservationNotFound;
  readonly invalid_state: InvalidState;
  readonly open_reservation_exists: OpenReservationExists;
  readonly forbidden: Forbidden;
  readonly idempotency_conflict: IdempotencyConflict;
  readonly stock_query: StockQuery;
  readonly receive_request: ReceiveRequest;
  readonly reserve_request: ReserveRequest;
  readonly release_request: ReleaseRequest;
  readonly ship_request: ShipRequest;
  readonly expire_request: ExpireRequest;
  readonly adjustment: Adjustment;
  readonly receipt: Receipt;
  readonly reservation_made: ReservationMade;
  readonly reservation_changed: ReservationChanged;
  readonly adjustment_made: AdjustmentMade;
}

/** Checks a value against a definition: its structure, then each rule. */
export function check<D extends DefinitionName>(definition: D, value: unknown): CheckResult<DefinitionTypes[D]> {
  const failures: Failure[] = [];
  return CHECKS[definition](value, '', failures) ? { ok: true, domain: DOMAIN, value: value as DefinitionTypes[D] } : { ok: false, domain: DOMAIN, failures };
}

/** What an operation answers: one of its outputs, by name, and its value. */
export interface Answer<O extends string, V> {
  readonly output: O;
  readonly value: V;
}

/** An answer of the core: answer('booking', booking). */
export function answer<O extends string, V>(output: O, value: V): Answer<O, V> {
  return { output, value };
}

/** The answers of get_stock. */
export type GetStockAnswer = Answer<"stock_level", StockLevel> | Answer<"unknown_sku", UnknownSku> | Answer<"unknown_location", UnknownLocation>;

/** The answers of receive_goods. */
export type ReceiveGoodsAnswer = Answer<"receipt", Receipt> | Answer<"unknown_sku", UnknownSku> | Answer<"unknown_location", UnknownLocation> | Answer<"forbidden", Forbidden>;

/** The answers of reserve_stock. */
export type ReserveStockAnswer = Answer<"reservation_made", ReservationMade> | Answer<"insufficient_stock", InsufficientStock> | Answer<"open_reservation_exists", OpenReservationExists> | Answer<"unknown_sku", UnknownSku> | Answer<"unknown_location", UnknownLocation> | Answer<"forbidden", Forbidden>;

/** The answers of release_reservation. */
export type ReleaseReservationAnswer = Answer<"reservation_changed", ReservationChanged> | Answer<"reservation_not_found", ReservationNotFound> | Answer<"invalid_state", InvalidState> | Answer<"forbidden", Forbidden>;

/** The answers of ship_reservation. */
export type ShipReservationAnswer = Answer<"reservation_changed", ReservationChanged> | Answer<"invalid_request", InvalidRequest> | Answer<"reservation_not_found", ReservationNotFound> | Answer<"invalid_state", InvalidState> | Answer<"forbidden", Forbidden>;

/** The answers of expire_reservation. */
export type ExpireReservationAnswer = Answer<"reservation_changed", ReservationChanged> | Answer<"invalid_request", InvalidRequest> | Answer<"reservation_not_found", ReservationNotFound> | Answer<"invalid_state", InvalidState> | Answer<"forbidden", Forbidden>;

/** The answers of adjust_stock. */
export type AdjustStockAnswer = Answer<"adjustment_made", AdjustmentMade> | Answer<"insufficient_stock", InsufficientStock> | Answer<"unknown_sku", UnknownSku> | Answer<"unknown_location", UnknownLocation> | Answer<"forbidden", Forbidden>;

/** The core: a function for each operation, from its input to one of its answers. */
export interface DomainCore {
  /** Read the stock of one SKU at one location */
  readonly get_stock: (input: StockQuery) => GetStockAnswer;
  /** Add received goods to the on-hand stock */
  readonly receive_goods: (input: ReceiveRequest) => ReceiveGoodsAnswer;
  /** Reserve every line in full, or nothing */
  readonly reserve_stock: (input: ReserveRequest) => ReserveStockAnswer;
  /** Give the stock of an active or partly shipped reservation back */
  readonly release_reservation: (input: ReleaseRequest) => ReleaseReservationAnswer;
  /** Ship a reservation, in full or the stated quantity per line */
  readonly ship_reservation: (input: ShipRequest) => ShipReservationAnswer;
  /** Expire an active reservation whose expiry time has come, and give its stock back */
  readonly expire_reservation: (input: ExpireRequest) => ExpireReservationAnswer;
  /** Correct the on-hand count of one SKU at one location */
  readonly adjust_stock: (input: Adjustment) => AdjustStockAnswer;
}

